text:
Here's your water tracker. Tap + for each glass, and it shows your progress toward 8 glasses today. It saves on this device and starts fresh each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; text-align: center; background: #f2f8fc; color: #12344d; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  .sub { color: #5b7a90; font-size: 14px; margin-bottom: 20px; }
  .count { font-size: 56px; font-weight: 700; margin: 8px 0; }
  .bar { height: 14px; background: #d9e8f2; border-radius: 7px; overflow: hidden; max-width: 320px; margin: 0 auto 20px; }
  .fill { height: 100%; width: 0; background: #2f9be0; transition: width .3s; }
  .glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 320px; margin: 0 auto 20px; }
  .g { width: 36px; height: 44px; border: 2px solid #2f9be0; border-radius: 4px 4px 10px 10px; background: #fff; }
  .g.on { background: #2f9be0; }
  button { font-size: 18px; padding: 10px 22px; margin: 4px; border: 0; border-radius: 8px; background: #2f9be0; color: #fff; cursor: pointer; }
  button.alt { background: #d9e8f2; color: #12344d; }
  #msg { margin-top: 16px; font-weight: 600; min-height: 24px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="sub" id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="glasses"></div>
  <div>
    <button class="alt" id="minus">−</button>
    <button id="plus">+ Add a glass</button>
  </div>
  <div><button class="alt" id="reset">Reset today</button></div>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var count = 0;
  try { count = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, String(count)); } catch (e) {} }

  function draw() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("n").textContent = count;
    document.getElementById("fill").style.width = Math.min(100, count / GOAL * 100) + "%";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < count ? " on" : "");
      box.appendChild(d);
    }
    var m = document.getElementById("msg");
    if (count >= GOAL) m.textContent = "Goal reached. Well done!";
    else m.textContent = (GOAL - count) + " more to go";
  }

  document.getElementById("plus").onclick = function () { count++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (count > 0) count--; save(); draw(); };
  document.getElementById("reset").onclick = function () { count = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
